# Convert .env.test to JSON (ignoring comments and empty lines) and send to deployment orchestrator
JSON_PAYLOAD=$(awk '
    BEGIN {printf "{"}
    /^[[:space:]]*#/ || /^[[:space:]]*$/ {next}  # Skip comments and empty lines
    NF > 0 {
        if ( NR == 1 || prev_line != "" ) { 
            printf "," 
        }
        split($0, parts, "=");
        printf "\"%s\":\"%s\"", parts[1], parts[2]
        prev_line = "set"
    }
    END {printf "}"}
' "$ENV_FILE")

